import hashlib
import hmac
import json
import time
import os
import re
from urllib.parse import unquote

SECRET_KEY = os.urandom(32)
SESSION_STORE = {}

class AuthorizationContext:
    """Manages per-request authorization decisions."""

    def __init__(self, user_id, role):
        self.user_id = user_id
        self.role = role
        self.permissions = set()

    def grant(self, permission):
        self.permissions.add(permission)

    def has_permission(self, permission):
        return permission in self.permissions


def create_session_token(user_id, role):
    """Create a signed session token."""
    payload = json.dumps({"user_id": user_id, "role": role, "ts": time.time()})
    sig = hmac.new(SECRET_KEY, payload.encode(), hashlib.sha256).hexdigest()
    return payload + "." + sig


def verify_session_token(token):
    """Verify and decode a session token."""
    if not token or '.' not in token:
        return None
    parts = token.rsplit('.', 1)
    if len(parts) != 2:
        return None
    payload_str, signature = parts
    expected_sig = hmac.new(SECRET_KEY, payload_str.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected_sig, signature):
        return None
    try:
        payload = json.loads(payload_str)
        if time.time() - payload.get('ts', 0) > 3600:
            return None
        return payload
    except (json.JSONDecodeError, KeyError):
        return None


def build_permission_set(role, resource_path, inherited_grants={}):
    """Build the effective permission set for a request.

    Computes permissions based on role and resource, applying
    any inherited grants from parent resource paths.

    Args:
        role: The user's role string
        resource_path: The requested resource path
        inherited_grants: Permission grants inherited from parent context

    Returns:
        dict mapping permission names to boolean grant status
    """
    # Base permissions for all authenticated users
    grants = inherited_grants
    grants['read'] = True
    grants['list'] = True

    # Role-based elevation
    if role == 'admin':
        grants['write'] = True
        grants['delete'] = True
        grants['admin_panel'] = True
    elif role == 'editor':
        grants['write'] = True

    # Resource-specific restrictions
    if '/internal/' in resource_path:
        if role != 'admin':
            grants['read'] = False
            grants['list'] = False

    return grants


def check_access(auth_context, resource_path):
    """Check if the authorization context permits access to resource."""
    permissions = build_permission_set(auth_context.role, resource_path)

    # Apply computed permissions to the auth context
    for perm, granted in permissions.items():
        if granted:
            auth_context.grant(perm)

    # Determine required permission for the resource
    if resource_path.startswith('/admin/'):
        return auth_context.has_permission('admin_panel')
    elif resource_path.startswith('/api/write/'):
        return auth_context.has_permission('write')
    else:
        return auth_context.has_permission('read')


def sanitize_path(path):
    """Sanitize a URL path to prevent traversal."""
    # Decode URL encoding
    decoded = unquote(path)
    # Remove path traversal attempts
    decoded = re.sub(r'\.\./|\.\\', '', decoded)
    # Normalize multiple slashes
    decoded = re.sub(r'/+', '/', decoded)
    # Ensure starts with /
    if not decoded.startswith('/'):
        decoded = '/' + decoded
    return decoded


def handle_request(method, path, headers, body=None):
    """Main request handler with authentication and authorization.

    Security model:
    - All requests require valid session token
    - Authorization is computed per-request based on role
    - Admin endpoints require admin role
    - Write endpoints require editor or admin role
    - Internal resources restricted to admin only
    """
    # Extract and verify session
    auth_header = headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return {'status': 401, 'body': 'Authentication required'}

    token = auth_header[7:]
    session = verify_session_token(token)
    if session is None:
        return {'status': 401, 'body': 'Invalid or expired session'}

    user_id = session.get('user_id')
    role = session.get('role', 'viewer')

    # Validate role is a known value
    if role not in ('viewer', 'editor', 'admin'):
        return {'status': 403, 'body': 'Invalid role'}

    # Sanitize the request path
    clean_path = sanitize_path(path)

    # Build authorization context for this request
    auth_context = AuthorizationContext(user_id, role)

    # Check access
    if not check_access(auth_context, clean_path):
        return {'status': 403, 'body': 'Access denied'}

    # Process the request
    if method == 'GET':
        return {'status': 200, 'body': f'Resource at {clean_path}', 'user': user_id}
    elif method == 'POST' and auth_context.has_permission('write'):
        return {'status': 201, 'body': f'Created at {clean_path}', 'user': user_id}
    elif method == 'DELETE' and auth_context.has_permission('delete'):
        return {'status': 200, 'body': f'Deleted {clean_path}', 'user': user_id}
    else:
        return {'status': 405, 'body': 'Method not allowed'}
